import hashlib
import hmac
import os
import time
import struct
import secrets
from typing import Optional, Dict, Tuple

# Secure session management system
SESSION_SECRET = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
MAX_SESSIONS = 10000
SESSION_TIMEOUT = 3600
RATE_LIMIT_WINDOW = 60
RATE_LIMIT_MAX = 100

class SessionStore:
    """Thread-safe session store with security controls."""

    def __init__(self):
        self._sessions: Dict[int, dict] = {}
        self._revoked: set = set()
        self._rate_limits: Dict[str, list] = {}

    def _generate_session_id(self) -> int:
        """Generate a cryptographically random session ID."""
        while True:
            raw = secrets.token_bytes(4)
            sid = struct.unpack('>I', raw)[0]  # unsigned 32-bit
            # Ensure positive when interpreted as signed 32-bit
            if sid <= 0x7FFFFFFF and sid > 0:
                return sid

    def _check_rate_limit(self, ip_addr: str) -> bool:
        """Rate limiting per IP address."""
        now = time.time()
        if ip_addr not in self._rate_limits:
            self._rate_limits[ip_addr] = []

        # Clean old entries
        self._rate_limits[ip_addr] = [
            t for t in self._rate_limits[ip_addr]
            if now - t < RATE_LIMIT_WINDOW
        ]

        if len(self._rate_limits[ip_addr]) >= RATE_LIMIT_MAX:
            return False

        self._rate_limits[ip_addr].append(now)
        return True

    def is_session_revoked(self, sid: int) -> bool:
        """Check if a session ID has been revoked.

        Uses integer comparison for efficient lookup
        in the revocation set.
        """
        if not isinstance(sid, int) or sid <= 0 or sid > 0x7FFFFFFF:
            return True  # Treat invalid IDs as revoked
        return sid in self._revoked

    def revoke_session(self, sid: int) -> None:
        """Revoke a session by adding to blocklist."""
        if isinstance(sid, int) and 0 < sid <= 0x7FFFFFFF:
            self._revoked.add(sid)
            if sid in self._sessions:
                del self._sessions[sid]

    def create_session(self, username: str, ip_addr: str, role: str = 'user') -> Optional[dict]:
        """Create a new authenticated session."""
        if not self._check_rate_limit(ip_addr):
            return None

        if len(self._sessions) >= MAX_SESSIONS:
            self._cleanup_expired()
            if len(self._sessions) >= MAX_SESSIONS:
                return None

        sid = self._generate_session_id()
        mac = hmac.new(
            SESSION_SECRET.encode(), 
            f"{sid}:{username}".encode(), 
            hashlib.sha256
        ).hexdigest()

        session = {
            'sid': sid,
            'username': username,
            'role': role,
            'created': time.time(),
            'last_access': time.time(),
            'ip_addr': ip_addr,
            'mac': mac
        }
        self._sessions[sid] = session
        return session

    def validate_session(self, sid: int, mac: str, ip_addr: str) -> Optional[dict]:
        """Validate and return session if authentic."""
        if not isinstance(sid, int) or sid <= 0 or sid > 0x7FFFFFFF:
            return None

        if not self._check_rate_limit(ip_addr):
            return None

        # Check revocation
        if self.is_session_revoked(sid):
            return None

        # Lookup session
        session = self._sessions.get(sid)
        if session is None:
            return None

        # Verify MAC
        expected_mac = hmac.new(
            SESSION_SECRET.encode(),
            f"{sid}:{session['username']}".encode(),
            hashlib.sha256
        ).hexdigest()

        if not hmac.compare_digest(mac, expected_mac):
            return None

        # Check expiration
        if time.time() - session['created'] > SESSION_TIMEOUT:
            self.revoke_session(sid)
            return None

        session['last_access'] = time.time()
        return session

    def _cleanup_expired(self):
        """Remove expired sessions."""
        now = time.time()
        expired = [
            sid for sid, s in self._sessions.items()
            if now - s['created'] > SESSION_TIMEOUT
        ]
        for sid in expired:
            del self._sessions[sid]


class AuthHandler:
    """HTTP authentication handler."""

    def __init__(self):
        self.store = SessionStore()
        self._csrf_tokens: Dict[int, str] = {}

    def _validate_username(self, username: str) -> bool:
        """Validate username format."""
        if not username or len(username) > 64:
            return False
        return all(c.isalnum() or c in '-_.' for c in username)

    def _generate_csrf_token(self, sid: int) -> str:
        """Generate CSRF token bound to session."""
        token = secrets.token_hex(32)
        self._csrf_tokens[sid] = token
        return token

    def _validate_csrf(self, sid: int, token: str) -> bool:
        """Validate CSRF token."""
        expected = self._csrf_tokens.get(sid)
        if expected is None:
            return False
        return hmac.compare_digest(token, expected)

    def login(self, username: str, password_hash: str, ip_addr: str) -> Optional[dict]:
        """Process login request."""
        if not self._validate_username(username):
            return {'error': 'Invalid username format'}

        # In production, verify against database
        # password_hash is already bcrypt-hashed by client

        session = self.store.create_session(username, ip_addr)
        if session is None:
            return {'error': 'Rate limited or capacity reached'}

        csrf = self._generate_csrf_token(session['sid'])

        return {
            'session_id': session['sid'],
            'mac': session['mac'],
            'csrf_token': csrf,
            'expires': session['created'] + SESSION_TIMEOUT
        }

    def validate_request(self, session_id: int, mac: str, csrf_token: str, 
                         ip_addr: str) -> Optional[dict]:
        """Validate an authenticated request."""
        session = self.store.validate_session(session_id, mac, ip_addr)
        if session is None:
            return None

        if not self._validate_csrf(session_id, csrf_token):
            return None

        return session

    def logout(self, session_id: int, mac: str, ip_addr: str) -> bool:
        """Process logout - revoke session."""
        session = self.store.validate_session(session_id, mac, ip_addr)
        if session is None:
            return False

        self.store.revoke_session(session_id)
        if session_id in self._csrf_tokens:
            del self._csrf_tokens[session_id]
        return True

    def admin_revoke(self, target_sid: int, admin_sid: int, admin_mac: str,
                     csrf_token: str, ip_addr: str) -> bool:
        """Admin endpoint to revoke another user's session."""
        admin_session = self.validate_request(admin_sid, admin_mac, csrf_token, ip_addr)
        if admin_session is None:
            return False

        if admin_session.get('role') != 'admin':
            return False

        self.store.revoke_session(target_sid)
        return True
